    public CommandResult execute(CommandContext context) {
        if (!(context.cause().first() instanceof Player)) {
            plugin.sendMessage(context.cause().first(), "no-console");
            return CommandResult.success();
        }

        UUID uniqueId = ((Player) context.cause().first()).getUniqueId();
        if (core.getCooldownService().isTracked(uniqueId)) {
            plugin.sendMessage(context.cause().first(), "cooldown");
            return CommandResult.success();
        }

        Player receiver = (Player) context.cause().first();
        String targetSkin = context.requireOne("skin");
        boolean keepSkin = context.hasFlag("keep");

