        final Flag keepFlag = Flag.builder().addAliases("keep").build();
        return Command.builder()
                .addExecutor(this)
                .addParameter(skinParam)
                .addFlag(keepFlag)
                .permission(PomData.ARTIFACT_ID + ".command.setskin.base")
                .build();
    }
}

