        url = PomData.URL, description = PomData.DESCRIPTION)
public class ChangeSkinSponge implements PlatformPlugin<Object> {

    private final Path dataFolder;
    private final Logger logger;
    private final Injector injector;

    private final ChangeSkinCore core = new ChangeSkinCore(this);
    private final SpongeSkinAPI api = new SpongeSkinAPI(this);

    private boolean initialized;

    //We will place more than one config there (i.e. H2/SQLite database) -> sharedRoot = false
    @Inject
    ChangeSkinSponge(Logger logger, @ConfigDir(sharedRoot = false) Path dataFolder, Injector injector) {
        this.dataFolder = dataFolder;
        this.logger = logger;
        this.injector = injector.createChildInjector(binder -> binder.bind(ChangeSkinCore.class).toInstance(core));
    }

    @Listener
    public void onPreInit(GamePreInitializationEvent preInitEvent) {
        //load config and database
        try {
            core.load(true);
            initialized = true;
        } catch (Exception ex) {
            logger.error("Error initializing plugin. Disabling...", ex);
        }
    }

    @Listener
    public void onInit(GameInitializationEvent initEvent) {
        if (!initialized)
            return;

        CommandManager cmdManager = Sponge.getCommandManager();

        //command and event register
        cmdManager.register(this, injector.getInstance(SelectCommand.class).build(), "skin-select", "skinselect");
        cmdManager.register(this, injector.getInstance(InfoCommand.class).build(), "skin-info");
        cmdManager.register(this, injector.getInstance(UploadCommand.class).build(), "skin-upload");
        cmdManager.register(this, injector.getInstance(SetCommand.class).build(), "changeskin", "setskin", "skin");
        cmdManager.register(this, injector.getInstance(InvalidateCommand.class)
                .build(), "skininvalidate", "skin-invalidate");

        Sponge.getEventManager().registerListeners(this, injector.getInstance(LoginListener.class));

        //incoming channel
        ChannelRegistration channelReg = Sponge.getChannelRegistrar();
        String updateChannelName = new NamespaceKey(ARTIFACT_ID, UPDATE_SKIN_CHANNEL).getCombinedName();
        String permissionChannelName = new NamespaceKey(ARTIFACT_ID, CHECK_PERM_CHANNEL).getCombinedName();
        ChannelBinding.RawChannel updateChannel = channelReg.getOrCreateRaw(this, updateChannelName);
        ChannelBinding.RawChannel permChannel = channelReg.getOrCreateRaw(this, permissionChannelName);
        updateChannel.addListener(injector.getInstance(UpdateSkinListener.class));
        permChannel.addListener(injector.getInstance(CheckPermissionListener.class));
    }

    @Listener
    public void onShutdown(GameStoppingServerEvent stoppingServerEvent) {
        core.close();
    }

    public ChangeSkinCore getCore() {
        return core;
    }

    public SpongeSkinAPI getApi() {
        return api;
    }

    @Override
    public boolean hasSkinPermission(Object invoker, UUID uuid, boolean sendMessage) {
        if (invoker instanceof Player) {
            Player player = (Player) invoker;
            if (player.hasPermission(PomData.ARTIFACT_ID + ".skin.whitelist." + uuid)) {
                return true;
            }
        }

        //disallow - not whitelisted or blacklisted
        if (sendMessage && invoker != null) {
            sendMessage(invoker, "no-permission");
        }

        return false;
    }

    @Override
    public String getName() {
        return PomData.NAME;
    }

    @Override
    public Path getPluginFolder() {
        return dataFolder;
    }

    @Override
    public Logger getLog() {
        return logger;
    }

    @Override
    public void sendMessage(Object receiver, String key) {
        String message = core.getMessage(key);
        if (message != null && receiver != null) {
            Component text = LegacyComponentSerializer.legacySection().deserialize(message);
            if (receiver instanceof Player) {
                ((Player) receiver).sendMessage(text);
            } else if (receiver instanceof CommandCause) {
                ((CommandCause) receiver).sendMessage(text);
            }
        }
    }
}

